void ftyp_box_del(GF_Box *s)
{
        GF_FileTypeBox *ptr = (GF_FileTypeBox *) s;
        if (ptr->altBrand) gf_free(ptr->altBrand);
        gf_free(ptr);
}

GF_Box *ftyp_box_new()
